"""Decoder for caliper-docgen's interned `extract --json` output.

decode(doc) -> {key: {'name', 'file', 'rows': [names], 'layers': [{'type','file','size','used','members'}]}}
Rows are what a consumer lists: every name in the component's `props` propSets plus `notableInherited`.
Layers are the `inheritance` entries; `members` is resolved through `nameLists`, `used` through `nameLists` when it is
an id, else kept as given (a list, a bool, a count); None when the field is absent.
Every hash lookup is checked: a dangling id raises, so a schema change fails loudly instead of decoding to nothing.
"""
import json
import os


def _name_list(doc, ref):
    if ref is None:
        return None
    if isinstance(ref, str):
        return list(doc['nameLists'][ref])
    return list(ref)


def rows_of(doc, comp):
    names = []
    for ref in comp.get('props') or []:
        pset = doc['propSets'][ref] if isinstance(ref, str) else ref
        for name, pid in pset.items():
            if isinstance(pid, str):
                doc['props'][pid]  # dangling-id check
            names.append(name)
    for name, pid in (comp.get('notableInherited') or {}).items():
        if isinstance(pid, str):
            doc['props'][pid]
        names.append(name)
    seen, out = set(), []
    for n in names:
        if n not in seen:
            seen.add(n)
            out.append(n)
    return out


def layers_of(doc, comp):
    out = []
    for lay in comp.get('inheritance') or []:
        used = lay.get('used')
        if isinstance(used, str):
            used = _name_list(doc, used)
        out.append({
            'type': lay.get('typeName'),
            'file': lay.get('fileName'),
            'size': lay.get('totalProps'),
            'used': used,
            'members': _name_list(doc, lay.get('members')),
        })
    return out


def decode(doc):
    res = {}
    for key, comp in doc['components'].items():
        res[key] = {
            'name': comp.get('displayName') or key,
            'file': comp.get('filePath'),
            'rows': rows_of(doc, comp),
            'layers': layers_of(doc, comp),
        }
    return res


def load(path):
    with open(path) as f:
        return decode(json.load(f))


def check_against_rdt(decoded, rdt_path):
    """Decoded row count must equal `--format rdt`'s props count for the same component (matched by display name).
    Returns (checked, mismatches[list of (name, decoded, rdt)], skipped_ambiguous)."""
    with open(rdt_path) as f:
        rdt = json.load(f)
    by_name = {}
    for key, c in decoded.items():
        by_name.setdefault(c['name'], []).append(c)
    checked, bad, skipped = 0, [], 0
    for rname, rc in rdt.items():
        cands = by_name.get(rc.get('displayName') or rname, [])
        if len(cands) != 1:
            skipped += 1
            continue
        checked += 1
        n_rdt = len(rc.get('props') or {})
        if n_rdt != len(cands[0]['rows']):
            bad.append((rname, len(cands[0]['rows']), n_rdt))
    return checked, bad, skipped

