// Storybook dev-mode check. usage: node sb.mjs <run dir> <addon packages/storybook dir> <out.json>
// Prepares <run dir>/sb: a clone of oracle-run/sb-demo (APFS copy-on-write node_modules) whose addon symlink points at
// the given storybook package; starts `storybook dev` on a free port; loads Button, Badge, Card, Input in a real
// Chromium (npm playwright from prefetch/drv); reads the Controls table names, count, time to first rows (structural)
// and time of the last change of the table (checker answer). Always kills the server (process group) at the end.
import { spawn, execFileSync } from 'node:child_process'
import { createRequire } from 'node:module'
import { createServer } from 'node:net'
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const require = createRequire('/Users/gabe/Projects/caliper-fixtures/prefetch/drv/')
const { chromium } = require('playwright')
const [, , runDir, addonDir, outFile] = process.argv
const DEMO = '/Users/gabe/Projects/caliper-fixtures/oracle-run/sb-demo'
const SB = join(runDir, 'sb')
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

function prep() {
  rmSync(SB, { recursive: true, force: true })
  mkdirSync(SB, { recursive: true })
  for (const f of ['package.json', 'tsconfig.json']) cpSync(join(DEMO, f), join(SB, f))
  cpSync(join(DEMO, 'src'), join(SB, 'src'), { recursive: true })
  rmSync(join(SB, 'src', 'Z_AntButton.stories.tsx'), { force: true }) // reaches ../../../corpora; Vite cannot load antd anyway
  mkdirSync(join(SB, '.storybook'))
  const main = readFileSync(join(DEMO, '.storybook/main.ts'), 'utf8').replace(/, '\/Users[^']*ant-design[^']*'/, '')
  writeFileSync(join(SB, '.storybook/main.ts'), main)
  execFileSync('cp', ['-c', '-R', join(DEMO, 'node_modules'), join(SB, 'node_modules')]) // clone, not a copy
  rmSync(join(SB, 'node_modules/caliper-docgen-storybook'), { force: true })
  symlinkSync(addonDir, join(SB, 'node_modules/caliper-docgen-storybook'))
  rmSync(join(SB, 'node_modules/.cache/caliper-docgen'), { recursive: true, force: true }) // cold Caliper cache
}

const freePort = () =>
  new Promise((res) => {
    const s = createServer()
    s.listen(0, '127.0.0.1', () => {
      const { port } = s.address()
      s.close(() => res(port))
    })
  })

// In the page: record the Controls table's name signature every 10 ms.
const SAMPLER = () => {
  window.__samples = []
  const names = () =>
    [...document.querySelectorAll('table tbody tr')]
      .map((tr) => (tr.querySelector('td') ? tr.querySelector('td').innerText.split('\n')[0].trim() : ''))
      .filter(Boolean)
  window.__names = names
  const t = performance.now()
  window.__iv = setInterval(() => {
    const n = names()
    window.__samples.push([Math.round(performance.now() - t), n.length, n.join('|')])
  }, 10)
}

const result = { stories: {} }
let server
try {
  prep()
  const port = await freePort()
  const t0 = Date.now()
  server = spawn(process.execPath, ['node_modules/storybook/dist/bin/dispatcher.js', 'dev', '-p', String(port), '--ci'], {
    cwd: SB,
    env: { ...process.env, STORYBOOK_DISABLE_TELEMETRY: '1' },
    stdio: ['ignore', 'pipe', 'pipe'],
    detached: true,
  })
  let log = ''
  server.stdout.on('data', (d) => (log += d))
  server.stderr.on('data', (d) => (log += d))
  let index
  for (;;) {
    if (Date.now() - t0 > 180_000 || server.exitCode !== null) throw new Error(`no index.json:\n${log.slice(-1500)}`)
    try {
      const r = await fetch(`http://localhost:${port}/index.json`)
      if (r.ok) {
        index = await r.json()
        break
      }
    } catch {}
    await sleep(100)
  }
  result.port = port
  result.readyMs = Date.now() - t0
  const browser = await chromium.launch()
  const page = await browser.newPage({ viewport: { width: 1400, height: 1000 } })
  const wanted = { Button: 'demo-b-button', Badge: 'demo-a-badge', Card: 'demo-c-card', Input: 'demo-d-input' }
  for (const [name, prefix] of Object.entries(wanted)) {
    const entry = Object.values(index.entries).find((e) => e.type === 'story' && e.id.startsWith(prefix + '--'))
    if (!entry) {
      result.stories[name] = { error: `no story ${prefix}` }
      continue
    }
    await page.goto('about:blank')
    const nav = Date.now()
    await page.goto(`http://localhost:${port}/?path=/story/${entry.id}&addonPanel=storybook/controls/panel`)
    await page.evaluate(SAMPLER)
    const deadline = Date.now() + 60_000
    let samples = []
    // Wait for rows, then until the table has been unchanged for 3 s (or 15 s after the first rows).
    for (;;) {
      await sleep(250)
      samples = await page.evaluate(() => window.__samples)
      const firstIdx = samples.findIndex((s) => s[1] > 0)
      const last = samples[samples.length - 1]
      if (firstIdx >= 0 && last) {
        const lastChange = samples.reduce((acc, s, i) => (i > 0 && s[2] !== samples[i - 1][2] ? s[0] : acc), samples[firstIdx][0])
        if (last[0] - lastChange > 3000 || last[0] - samples[firstIdx][0] > 15_000) break
      }
      if (Date.now() > deadline) break
    }
    const firstIdx = samples.findIndex((s) => s[1] > 0)
    const finalRows = samples.length ? samples[samples.length - 1][2].split('|').filter(Boolean) : []
    let checkerAt = null
    for (let i = Math.max(firstIdx, 1); i < samples.length; i++) if (samples[i][2] !== samples[i - 1][2]) checkerAt = samples[i][0]
    result.stories[name] = {
      id: entry.id,
      rows: finalRows,
      count: finalRows.length,
      structuralMs: firstIdx >= 0 ? samples[firstIdx][0] : null, // ms after the page's sampler started (just after goto)
      structuralCount: firstIdx >= 0 ? samples[firstIdx][1] : 0,
      checkerMs: checkerAt, // last change of the table; null if it never changed after first rows
      gotoToSamplerMs: Date.now() - nav,
    }
  }
  await browser.close()
} catch (e) {
  result.error = String(e?.message ?? e).slice(0, 2000)
} finally {
  if (server) {
