  result.error = String(e?.message ?? e).slice(0, 2000)
} finally {
  if (server) {
    try {
      process.kill(-server.pid, 'SIGKILL')
    } catch {}
  }
  try {
    if (result.port) execFileSync('sh', ['-c', `lsof -ti tcp:${result.port} | xargs kill -9 2>/dev/null; true`])
  } catch {}
}
